<?php
declare(strict_types=1);
namespace App\Application\QuestionLearning\Service;
use App\Application\QuestionLearning\DTO\Request\SaveQuestionNoteRequestDto;use App\Application\QuestionLearning\DTO\Response\QuestionNoteResponseDto;use App\Application\QuestionLearning\Mapper\QuestionNoteResponseMapper;use App\Domain\QuestionBank\Repository\FrozenQuestionReaderInterface;use App\Domain\QuestionLearning\Entity\QuestionNote;use App\Domain\QuestionLearning\Repository\QuestionNoteRepositoryInterface;
final readonly class SaveQuestionNoteService { public function __construct(private FrozenQuestionReaderInterface $questions, private QuestionNoteRepositoryInterface $notes, private QuestionNoteResponseMapper $mapper) {} public function execute(string $userId, SaveQuestionNoteRequestDto $request, \DateTimeImmutable $now): QuestionNoteResponseDto { if (count($this->questions->findByIds([$request->questionId])) !== 1) { throw new \DomainException('Questão não encontrada.'); } $note = $this->notes->findForUserQuestion($userId, $request->questionId); if ($note === null) { $note = new QuestionNote($this->uuid(), $userId, $request->questionId, $request->content, $now, $now); } else { $note->update($request->content, $now); } $this->notes->save($note); return $this->mapper->toResponse($note); } private function uuid(): string { $bytes = random_bytes(16); $bytes[6] = chr((ord($bytes[6]) & 15) | 64); $bytes[8] = chr((ord($bytes[8]) & 63) | 128); return vsprintf('%s%s-%s-%s-%s-%s%s%s', str_split(bin2hex($bytes), 4)); } }
